// Naive suffix array construction

vector<int> naiveSuffixArray(const string& s) {
    int n = s.size();
    vector<int> sa(n);
    iota(sa.begin(), sa.end(), 0);

    sort(sa.begin(), sa.end(), [&](int i, int j) {
        return s.substr(i) < s.substr(j);   // O(n) comparison
    });

    return sa;
}

// C++ — Suffix Array construction using rank doubling

vector<int> buildSuffixArray(const string& s) {
    int n = s.size();
    vector<int> sa(n), rnk(n), tmp(n);

    // Round 0: rank by the first 1 character
    for (int i = 0; i < n; i++) {
        sa[i] = i;
        rnk[i] = (unsigned char)s[i];
    }

    for (int k = 1; k < n; k <<= 1) {
        auto cmp = [&](int a, int b) {
            if (rnk[a] != rnk[b]) return rnk[a] < rnk[b];
            int ra = (a + k < n) ? rnk[a + k] : -1;
            int rb = (b + k < n) ? rnk[b + k] : -1;
            return ra < rb;
        };

        sort(sa.begin(), sa.end(), cmp);

        // Re-rank suffixes based on the new sorted order
        tmp[sa[0]] = 0;
        for (int i = 1; i < n; i++) {
            tmp[sa[i]] = tmp[sa[i - 1]] + (cmp(sa[i - 1], sa[i]) ? 1 : 0);
        }
        rnk = tmp;

        if (rnk[sa[n - 1]] == n - 1) break;   // every suffix already has a distinct rank
    }

    return sa;
}

// C++ — Kasai's algorithm: build LCP array in O(n) from the suffix array

vector<int> buildLCPArray(const string& s, const vector<int>& sa) {
    int n = s.size();
    vector<int> rankOf(n), lcp(n, 0);

    for (int i = 0; i < n; i++) rankOf[sa[i]] = i;

    int h = 0;
    for (int i = 0; i < n; i++) {
        if (rankOf[i] > 0) {
            int j = sa[rankOf[i] - 1];
            while (i + h < n && j + h < n && s[i + h] == s[j + h]) h++;
            lcp[rankOf[i]] = h;
            if (h > 0) h--;
        } else {
            h = 0;
        }
    }
    return lcp;
}
